import sys, os, csv, json, io, re, configparser
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal


def pnum(s):
    d = re.sub(r"\D", "", s or "")
    return int(d) if d else None


def cents(s):
    return int((Decimal(s.strip().replace("$", "")) * 100).to_integral_value(rounding="ROUND_HALF_UP"))


def pdate(s):
    return date.fromisoformat(s.strip())


def parse_offset(s):
    s = s.strip()
    sign = -1 if s[0] == "-" else 1
    s = s.lstrip("+-")
    h, m = s.split(":")[:2]
    return sign * (int(h) * 60 + int(m))


def parse_instant(s):
    s = s.strip()
    m = re.match(r"^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:\.\d+)?)?\s*(Z|[+-]\d\d:?\d\d)?$", s)
    y, mo, d, h, mi, sec, tz = m.groups()
    dt = datetime(int(y), int(mo), int(d), int(h), int(mi), int(sec or 0))
    if tz and tz != "Z":
        t = tz if ":" in tz else tz[:3] + ":" + tz[3:]
        dt -= timedelta(minutes=parse_offset(t))
    return dt  # naive UTC


def main(inp, outp):
    cp = configparser.RawConfigParser(strict=False)
    cp.optionxform = str
    with open(os.path.join(inp, "policy.ini"), encoding="utf-8-sig") as f:
        cp.read_file(f)
    library = cp.get("statement", "library").strip()
    pstart = pdate(cp.get("statement", "period_start"))
    pend = pdate(cp.get("statement", "period_end"))
    base_off = parse_offset(cp.get("clock", "offset"))
    changes = []
    if cp.has_option("clock", "changes"):
        for part in cp.get("clock", "changes").split(";"):
            part = part.strip()
            if not part:
                continue
            a, b = part.split()
            changes.append((parse_instant(a), parse_offset(b)))
    changes.sort(key=lambda x: x[0])

    items = {}
    cats = {}
    for sec in cp.sections():
        if sec.lower().startswith("item:"):
            n = sec[5:].strip()
            g = lambda k: cp.get(sec, k).strip()
            items[n.lower()] = dict(name=n, loan_days=int(g("loan_days")), renewals=int(g("renewals")),
                                    grace=int(g("grace_days")), daily=cents(g("daily")), cap=cents(g("loan_cap")))
        elif sec.lower().startswith("category:"):
            n = sec[9:].strip()
            sc = cp.get(sec, "statement_cap").strip()
            ex = cp.get(sec, "exempt", fallback="")
            cats[n.lower()] = dict(name=n, cap=None if sc.lower() == "none" else cents(sc),
                                   disc=int(cp.get(sec, "discount").strip() or 0),
                                   exempt={x.strip().lower() for x in ex.split(",") if x.strip()})

    def rows(name):
        with open(os.path.join(inp, name), encoding="utf-8-sig", newline="") as f:
            return [{(k or "").strip(): (v or "").strip() for k, v in r.items()} for r in csv.DictReader(f)]

    WD = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
    branches = []
    open_days = {}
    for r in rows("branches.csv"):
        branches.append(r["branch"])
        open_days[r["branch"].lower()] = {w.lower()[:3] for w in r["open_days"].split()}
    cal_b = {}
    cal_all = {}
    for r in rows("calendar.csv"):
        ds = r["date"]
        if ".." in ds:
            a, b = ds.split("..")
        else:
            a = b = ds
        a, b = pdate(a), pdate(b)
        tgt = cal_all if r["branch"] == "*" else cal_b.setdefault(r["branch"].lower(), {})
        st = r["status"].lower() == "open"
        d = a
        while d <= b:
            tgt[d] = st
            d += timedelta(days=1)

    def is_open(br, d):
        b = br.lower()
        if b in cal_b and d in cal_b[b]:
            return cal_b[b][d]
        if d in cal_all:
            return cal_all[d]
        return WD[d.weekday()] in open_days.get(b, set())

    def next_open(br, d):
        for _ in range(3660):
            if is_open(br, d):
                return d
            d += timedelta(days=1)
        return d

    prow = {}
    pname = {}
    for r in rows("patrons.csv"):
        n = pnum(r["patron"])
        prow.setdefault(n, []).append((pdate(r["since"]), r["category"]))
        pname.setdefault(n, r["patron"])
    for n in prow:
        prow[n].sort(key=lambda x: x[0])

    def category(n, d):
        c = None
        for s, cat in prow[n]:
            if s <= d:
                c = cat
        if c is None:
            c = prow[n][0][1]
        return cats[c.lower()]

    waivers = []
    for r in rows("waivers.csv"):
        if r["status"].lower() != "active":
            continue
        v = r["value"].strip()
        waivers.append((pnum(r["patron"]), r["loan"], None if v.lower() == "full" else cents(v)))

    def local(dt_utc):
        off = base_off
        for t, o in changes:
            if dt_utc >= t:
                off = o
        return dt_utc + timedelta(minutes=off)

    # events
    events = {}
    exdir = os.path.join(inp, "exports")
    for fn in sorted(os.listdir(exdir)):
        p = os.path.join(exdir, fn)
        low = fn.lower()
        if not os.path.isfile(p):
            continue
        if low.endswith(".csv"):
            with open(p, encoding="utf-8-sig", newline="") as f:
                for r in csv.DictReader(f):
                    r = {(k or "").strip(): (v or "").strip() for k, v in r.items()}
                    if not r.get("event"):
                        continue
                    r["_t"] = datetime.strptime(r["time"], "%Y-%m-%d %H:%M") if r.get("time") else None
                    events.setdefault(r["event"], r)
        elif low.endswith(".jsonl"):
            with open(p, encoding="utf-8-sig") as f:
                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    o = json.loads(line)
                    r = {k: ("" if v is None else str(v).strip()) for k, v in o.items()}
                    if not r.get("event"):
                        continue
                    r["_t"] = local(parse_instant(r["at"])) if r.get("at") else None
                    events.setdefault(r["event"], r)

    cancelled = {e["target"] for e in events.values() if e.get("type", "").lower() == "void" and e.get("target")}
    live = [e for k, e in events.items() if k not in cancelled and e.get("type", "").lower() != "void"]

    checkouts = {}
    later = {}
    for e in live:
        t = e["type"].lower()
        if t == "checkout":
            checkouts[e["loan"]] = e
        elif t in ("renew", "return"):
            later.setdefault(e["loan"], []).append(e)

    loans = []
    for lid, c in checkouts.items():
        co = c["_t"].date()
        if co > pend:
            continue
        it = items[c["item_type"].lower()]
        br = c["branch"]
        due = next_open(br, co + timedelta(days=it["loan_days"]))
        nren = 0
        ret = None
        for e in sorted(later.get(lid, []), key=lambda e: e["_t"]):
            d = e["_t"].date()
            if e["type"].lower() == "renew":
                if d <= due and nren < it["renewals"] and d <= pend:
                    nren += 1
                    due = next_open(br, d + timedelta(days=it["loan_days"]))
            else:
                ret = d
                if e.get("via", "").lower() == "dropbox":
                    ret -= timedelta(days=1)
                break
        if ret is not None and ret < pstart:
            continue
        if ret is not None and ret > pend:
            ret = None
        end = ret if ret is not None else pend
        od = 0
        d = due + timedelta(days=1)
        while d <= end:
            if is_open(br, d):
                od += 1
            d += timedelta(days=1)
        if od == 0:
            continue
        pn = pnum(c["patron"])
        charged = od if od > it["grace"] else 0
        cat = category(pn, co)
        fee = charged * it["daily"]
        if it["name"].lower() in cat["exempt"]:
            fee = 0
        fee = min(fee, it["cap"])
        assessed = (fee * (100 - cat["disc"]) + 50) // 100
        loans.append(dict(pn=pn, loan=lid, item=c["item"], item_type=it["name"], branch=br, checkout=co, due=due,
                          returned=ret, od=od, ch=charged, assessed=assessed))

    bypat = {}
    for l in loans:
        bypat.setdefault(l["pn"], []).append(l)
    statements = []
    for pn in sorted(bypat):
        ls = sorted(bypat[pn], key=lambda l: (l["due"], l["loan"]))
        ws = [w for w in waivers if w[0] == pn]
        for l in ls:
            ap = [w for w in ws if w[1] == "*" or w[1] == l["loan"]]
            if any(w[2] is None for w in ap):
                l["waived"] = l["assessed"]
            else:
                l["waived"] = min(l["assessed"], sum(w[2] for w in ap))
            l["net"] = l["assessed"] - l["waived"]
            l["capped"] = 0
        cat = category(pn, pend)
        if cat["cap"] is not None:
            excess = sum(l["net"] for l in ls) - cat["cap"]
            for l in reversed(ls):
                if excess <= 0:
                    break
                g = min(excess, l["net"])
                l["capped"] = g
                excess -= g
        for l in ls:
            l["billed"] = l["net"] - l["capped"]
        s = dict(patron=pname[pn], category=cat["name"], loans=[
            dict(loan=l["loan"], item=l["item"], item_type=l["item_type"], branch=l["branch"],
                 checkout=l["checkout"].isoformat(), due=l["due"].isoformat(),
                 returned=l["returned"].isoformat() if l["returned"] else None,
                 overdue_days=l["od"], charged_days=l["ch"], assessed=l["assessed"], waived=l["waived"],
                 capped=l["capped"], billed=l["billed"]) for l in ls])
        for k in ("assessed", "waived", "capped", "billed"):
            s[k] = sum(l[k] for l in ls)
        statements.append(s)

    bsum = []
    for b in branches:
        ls = [l for s in statements for l in s["loans"] if l["branch"].lower() == b.lower()]
        d = dict(branch=b, loans=len(ls), charged_days=sum(l["charged_days"] for l in ls))
        for k in ("assessed", "waived", "capped", "billed"):
            d[k] = sum(l[k] for l in ls)
        bsum.append(d)
    out = dict(library=library, period=dict(start=pstart.isoformat(), end=pend.isoformat()),
               statements=statements, branches=bsum)
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(out, f, indent=1, ensure_ascii=False)


main(sys.argv[1], sys.argv[2])
